import sys

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.rsplit(' ', 1)
        if len(parts) != 2:
            continue
        S, K_str = parts
        K = int(K_str)
        result = []
        for i in range(K - 1, len(S), K):
            result.append(S[i])
        print(' '.join(result))

if __name__ == "__main__":
    main()
